// ============================================
// VALIDATE INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// Extract project_id from header
const projectId = headers['x-project-id'] || headers['X-Project-ID'] || 'default';

// Required fields
const errors = [];

if (!body.guild_id) errors.push('guild_id');

// Validate mode
const validModes = ['check', 'repair'];
const mode = body.mode || 'check';
if (!validModes.includes(mode)) {
  errors.push(`mode must be one of: ${validModes.join(', ')}`);
}

if (errors.length > 0) {
  return {
    valid: false,
    error: {
      code: 400,
      message: `Paramètres invalides: ${errors.join(', ')}`,
      status: 'BAD_REQUEST'
    }
  };
}

return {
  valid: true,
  project_id: projectId,
  data: {
    guild_id: body.guild_id,
    mode: mode
  }
};

// ============================================
// CHECK API RESPONSE
// ============================================

const apiResponse = $input.first().json;
const inputData = $('Validate Input').first().json;

// Check for API error
if (apiResponse.error || apiResponse.statusCode >= 400) {
  return {
    success: false,
    error: {
      code: apiResponse.statusCode || 500,
      message: apiResponse.message || apiResponse.error || 'API error',
      status: 'API_ERROR'
    }
  };
}

// Extract promotions
const promotions = apiResponse.data || apiResponse.promotions || apiResponse || [];

return {
  success: true,
  guild_id: inputData.data.guild_id,
  mode: inputData.data.mode,
  promotions: Array.isArray(promotions) ? promotions : [promotions],
  project_id: inputData.project_id
};

// ============================================
// COMPARE AND DETECT ANOMALIES
// ============================================

const apiData = $('Check API Response').first().json;
const discordResponse = $input.first().json;

const promotions = apiData.promotions || [];
const discordStructures = discordResponse.data || discordResponse.structures || discordResponse || [];

// Build lookup maps
const discordByPromotionId = new Map();
for (const structure of (Array.isArray(discordStructures) ? discordStructures : [])) {
  if (structure.promotion_id) {
    discordByPromotionId.set(structure.promotion_id, structure);
  }
}

// Detect anomalies
const anomalies = [];
const syncActions = [];

for (const promotion of promotions) {
  const discordStructure = discordByPromotionId.get(promotion.id);

  if (!discordStructure) {
    // Promotion without Discord structure
    anomalies.push({
      type: 'MISSING_DISCORD_STRUCTURE',
      severity: 'high',
      promotion_id: promotion.id,
      promotion_name: promotion.formation?.name || promotion.name,
      year: `${promotion.year_start}-${promotion.year_end}`,
      message: `Structure Discord manquante pour la promotion ${promotion.id}`
    });
    syncActions.push({
      action: 'CREATE_STRUCTURE',
      promotion_id: promotion.id,
      promotion: promotion
    });
  } else {
    // Check individual components
    if (!discordStructure.category_id) {
      anomalies.push({
        type: 'MISSING_CATEGORY',
        severity: 'high',
        promotion_id: promotion.id,
        message: `Catégorie Discord manquante`
      });
    }
    if (!discordStructure.role_id) {
      anomalies.push({
        type: 'MISSING_ROLE',
        severity: 'high',
        promotion_id: promotion.id,
        message: `Rôle Discord manquant`
      });
    }
    // Check channels
    const expectedChannels = ['general', 'annonces', 'ressources'];
    const existingChannels = discordStructure.channels || [];
    for (const expected of expectedChannels) {
      if (!existingChannels.some(c => c.type === expected || c.name?.includes(expected))) {
        anomalies.push({
          type: 'MISSING_CHANNEL',
          severity: 'medium',
          promotion_id: promotion.id,
          channel_type: expected,
          message: `Channel '${expected}' manquant`
        });
      }
    }
  }
}

// Check for orphan Discord structures (in Discord but not in API)
for (const [promotionId, structure] of discordByPromotionId) {
  if (!promotions.find(p => p.id === promotionId)) {
    anomalies.push({
      type: 'ORPHAN_DISCORD_STRUCTURE',
      severity: 'low',
      promotion_id: promotionId,
      category_id: structure.category_id,
      message: `Structure Discord orpheline (promotion supprimée de l'API)`
    });
  }
}

return {
  guild_id: apiData.guild_id,
  mode: apiData.mode,
  promotions_count: promotions.length,
  discord_structures_count: discordByPromotionId.size,
  anomalies: anomalies,
  anomalies_count: anomalies.length,
  sync_actions: syncActions,
  has_anomalies: anomalies.length > 0
};

// ============================================
// PREPARE REPAIR EVENTS
// ============================================

const data = $input.first().json;
const syncActions = data.sync_actions || [];

// Prepare events for each action (format RFC-023)
const events = [];
for (const action of syncActions) {
  if (action.action === 'CREATE_STRUCTURE') {
    const promotion = action.promotion;
    events.push({
      event: 'promotion.repair_structure',
      guild_id: data.guild_id,
      timestamp: new Date().toISOString(),
      data: {
        promotion_id: action.promotion_id,
        formation_id: promotion.formation_id || promotion.formation?.id,
        formation_name: promotion.formation?.name || promotion.name,
        formation_emoji: promotion.formation?.emoji || '🎓',
        year_start: promotion.year_start,
        year_end: promotion.year_end,
        matieres: promotion.matieres || []
      }
    });
  }
}

return {
  ...data,
  repair_events: events,
  stream_name: 'formation:events:stream'
};

// ============================================
// SPLIT EVENTS FOR PUBLISHING
// ============================================

const data = $input.first().json;
const events = data.repair_events || [];

if (events.length === 0) {
  return {
    ...data,
    events_published: 0
  };
}

// Return each event for loop processing
return events.map(event => ({
  json: {
    event: event,
    stream_name: data.stream_name,
    original_data: data
  }
}));

// ============================================
// PREPARE FINAL REPORT (REPAIR MODE)
// ============================================

const items = $input.all();
const originalData = items[0]?.json?.original_data || $('Prepare Repair Events').first().json;

return {
  success: true,
  mode: 'repair',
  guild_id: originalData.guild_id,
  report: {
    promotions_checked: originalData.promotions_count,
    discord_structures_found: originalData.discord_structures_count,
    anomalies_detected: originalData.anomalies_count,
    anomalies: originalData.anomalies,
    repairs_attempted: originalData.sync_actions.length,
    events_published: items.length
  },
  message: `Réconciliation terminée: ${originalData.anomalies_count} anomalies détectées, ${items.length} réparations lancées`
};

// ============================================
// PREPARE FINAL REPORT (CHECK MODE)
// ============================================

const data = $input.first().json;

return {
  success: true,
  mode: 'check',
  guild_id: data.guild_id,
  report: {
    promotions_checked: data.promotions_count,
    discord_structures_found: data.discord_structures_count,
    anomalies_detected: data.anomalies_count,
    anomalies: data.anomalies,
    suggested_repairs: data.sync_actions.length
  },
  message: data.has_anomalies 
    ? `${data.anomalies_count} anomalies détectées. Utilisez mode=repair pour corriger.`
    : 'Aucune anomalie détectée. Tout est synchronisé.'
};
